NoAccessException noAccess = new NoAccessException();
noAccess.setMessage('blocked value');
System.assertEquals('System.NoAccessException', noAccess.getTypeName());
System.assertEquals('System.NoAccessException: blocked value', noAccess.toString());
System.assert(noAccess.equals(noAccess));
System.assert(!noAccess.equals(new NoAccessException()));
System.assertEquals(noAccess.hashCode(), noAccess.hashCode());
NoDataFoundException noData = new NoDataFoundException();
noData.setMessage('missing value');
System.assertEquals('System.NoDataFoundException', noData.getTypeName());
System.assertEquals('System.NoDataFoundException: missing value', noData.toString());
System.assert(noData.equals(noData));
System.assert(!noData.equals(new NoDataFoundException()));
System.assertEquals(noData.hashCode(), noData.hashCode());

